style.css:
@-moz-document domain("roblox.com") {
/* === Universal Background Enforcement === */
    :root, html, body {
        background-image: url("https://i.imgur.com/Tnr21iW.jpeg") !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        background-size: cover !important;
        background-color: #000 !important;
    }

    /* Force image layer behind everything */
    body::before {
        content: "" !important;
        position: fixed !important;
        top: 0 !important;
        left: 0 !important;
        width: 100vw !important;
        height: 100vh !important;
        background: url("https://i.imgur.com/Tnr21iW.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
        z-index: -9999 !important;
        opacity: 1 !important;
        pointer-events: none !important;
    }

    /* Make all Roblox containers transparent */
    #container-main, .container-main, .page-content, #content, .content,
    .rbx-body, .rbx-main-content, .game-page-container, .content-area,
    .section-content, .profile-container, .games-page, .games-content {
        background: transparent !important;
        backdrop-filter: none !important;
        box-shadow: none !important;
    }

    /* Overlay for text readability */
    html::after {
        content: "" !important;
        position: fixed !important;
        top: 0 !important;
        left: 0 !important;
        width: 100vw !important;
        height: 100vh !important;
        background: rgba(10, 5, 5, 0.6) !important;
        z-index: -998 !important;
        pointer-events: none !important;
    }

    /* Navbar & footer styling */
    .navbar, .header, .nav-menu, .footer-container {
        background: rgba(20, 15, 25, 0.8) !important;
        border-bottom: 1px solid rgba(255, 192, 203, 0.3) !important;
        color: #ffd6e8 !important;
    }

    /* Text */
    h1, h2, h3, h4, h5, h6, p, span, label, strong {
        color: #ffe0ec !important;
    }

    /* Links */
    a, .text-link {
        color: #ffb6c1 !important;
        text-decoration: none !important;
        transition: color 0.2s ease, text-shadow 0.2s ease;
    }

    a:hover, .text-link:hover {
        color: #ffd1dc !important;
        text-shadow: 0 0 5px #ff99bb !important;
    }

    /* Buttons */
    .btn-primary, .btn-growth-lg, .btn-common-lg {
        background-color: rgba(255, 182, 193, 0.25) !important;
        border: 1px solid #ff99bb !important;
        color: #ffe6f0 !important;
        transition: all 0.3s ease !important;
    }

    .btn-primary:hover, .btn-growth-lg:hover {
        background-color: rgba(255, 192, 203, 0.4) !important;
        color: #fff !important;
        box-shadow: 0 0 10px #ff99bb !important;
    }

    /* Cards & panels */
    .card-item, .game-card, .section-content, .profile-container, .message-content, .notification-content {
        background-color: rgba(0, 0, 0, 0.55) !important;
        border: 1px solid rgba(255, 182, 193, 0.25) !important;
        color: #f8e8ee !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-track {
        background: rgba(0, 0, 0, 0.5);
    }
    ::-webkit-scrollbar-thumb {
        background-color: #ff99bb;
        border-radius: 10px;
    }
}
